export type QuestionView = { round: string | null, number: number, id: string, version: number, text_html: string, door: Door | null, context_html: string | null, sections: Array<SectionView>, recommendation: Recommendation, choices: Array<ChoiceView>, citations: Array<CitationView>, marks: MarksView | null, gain: GainView | null, answerable: boolean, revision: RevisionView | null, };
